import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"Product Scope And Architecture","description":"","frontmatter":{"docLocale":"en","counterpart":"/architecture/lab-word","contentType":"concept","prev":false,"next":false},"headers":[],"relativePath":"en/architecture/lab-word.md","filePath":"en/architecture/lab-word.md"}'),i={name:"en/architecture/lab-word.md"};function s(o,e,d,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="product-scope-and-architecture" tabindex="-1">Product Scope And Architecture <a class="header-anchor" href="#product-scope-and-architecture" aria-label="Permalink to &quot;Product Scope And Architecture&quot;">​</a></h1><p>Lab Word is a laboratory digital twin. The application provides persistent Labs, independent Entities, multi-node scenes, a server Asset Library and versioned definitions. Users can edit layouts, register manual relationships and run backend lighting, temperature and centrifuge programs. See the <a href="https://github.com/CaiZongyuan/labworld/blob/847a4609ed29871c5721b4e03dc3edd3953b8f28/CONTEXT.md" target="_blank" rel="noreferrer">glossary</a>.</p><h2 id="models-and-equipment" tabindex="-1">Models And Equipment <a class="header-anchor" href="#models-and-equipment" aria-label="Permalink to &quot;Models And Equipment&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lab ──registers──&gt; Entity &lt;──defined by── Asset</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                    └──represented by Scene Node &lt;──appearance── Asset Representation</span></span></code></pre></div><p>This Foundation V1 identity relationship is implemented: an Equipment Model is a 3D representation, and an Equipment Instance is a device Entity. Scene Node identity and placement are independent of device identity. Multiple devices can share a model, and one device can have multiple nodes. Registration pins a definition version and snapshot. Simulated and physical objects have separate identities, and static objects require no Binding.</p><h2 id="existing-implementation-and-planned-integration" tabindex="-1">Existing Implementation And Planned Integration <a class="header-anchor" href="#existing-implementation-and-planned-integration" aria-label="Permalink to &quot;Existing Implementation And Planned Integration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Current state</th><th>Future responsibility</th></tr></thead><tbody><tr><td>Universal shell, identity, membership, knowledge</td><td>Existing application code</td><td>Host Lab and provide shared capabilities</td></tr><tr><td>Lab and persistent Asset Library</td><td>Members/Agents share worlds, layouts, files, device programs, history and lifecycle operations</td><td>Extend measured capacity for larger assets</td></tr><tr><td>Lab navigation and default entry after login</td><td>Integrated through explicit composition</td><td>Preserve shell and Lab ownership</td></tr><tr><td>Foundation V1</td><td>Implemented combined journey and isolated 100 Entity / 20 device / two-browser report</td><td>Evolve from recorded evidence</td></tr><tr><td>Physical devices and protocols</td><td>Future scope</td><td>Add source adapters and execution contracts</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/labworld/blob/847a4609ed29871c5721b4e03dc3edd3953b8f28/docs/adr/0005-lab-digital-twin-on-saas-foundation.md" target="_blank" rel="noreferrer">ADR 0005</a>chooses the existing SaaS foundation: Lab owns equipment and layout behavior while Core owns common identity and membership. See <a href="./project-structure">project structure</a> for integration locations.</p><h2 id="presentation-boundaries" tabindex="-1">Presentation Boundaries <a class="header-anchor" href="#presentation-boundaries" aria-label="Permalink to &quot;Presentation Boundaries&quot;">​</a></h2><p>The Lab entry has an object directory, multi-node scene and Inspector. Placement, configuration and references persist across browsers and Agents. Pointer transforms edit only Placement. Users register relationships with manual provenance. The API rejects invalid spatial cycles. Copies create independent Entities. Additional representations and node removal retain identity. Version conflicts keep the draft for explicit recovery. See the <a href="./../tutorials/edit-layout">layout tutorial</a>.</p><p>Definition support, Binding implementation and current executability remain separate. Absent observations are unknown. <a href="./../tutorials/backend-lights">Backend lights</a> distinguish command acceptance from observations. Stopping retains the last report. Interruption requires explicit startup. Layout versions remain separate from runtime state. <a href="./../tutorials/reliable-sync">World subscriptions</a> provide persistent versions, property updates, bounded queues and snapshot recovery. Credential revocation ends existing access. Service readiness and persistent capability permission jointly determine operability.</p><p><a href="./../tutorials/run-history">History</a> supports device, type, time range and cursor queries. Raw observations default to 24 hours. Ended commands, tasks and events default to 30 days. Cleanup keeps identities, configuration, last property observations and active tasks. Each retained property keeps its actual timestamps and freshness. Deleting expired current task records advances the world version. History gaps remain explicit. The asset library retains preview at <code>/lab/asset</code>. Core owns file lifecycles. Lab owns stable references.</p><p><a href="./../tutorials/entity-lifecycle">Entity lifecycle</a> requires ended Tasks and a stopped program before archive or definition changes. Archive retains identity, nodes, real asset references and records within retention. Appearance replacement works during running programs and Tasks. It updates the Entity and its current nodes without changing device behavior. Explicit catalog selection records the definition version. Supported simulated definitions receive a new current Binding. Other choices leave no current Binding. Old Runs retain the original association and source. The <a href="./../tutorials/complete-foundation">complete journey</a> verifies combined recovery and provides the isolated reference-load command.</p><p>Backend <a href="./../tutorials/continuous-temperature">temperature sensors</a> sample independently at 1Hz. Each property retains value, unit, source, timestamps and quality. Heartbeats do not refresh old measurements. Stopping a source keeps its last value. The report deadline determines expiry. Expiry advances the world version and preserves layout drafts.</p><p>The backend advances <a href="./../tutorials/centrifuge-tasks">centrifuge tasks</a> after browsers close. Commands, Runs, Tasks and results have separate queryable identities. Each task freezes its speed, temperature and duration. Timing starts after speed and temperature reach tolerance. Preparation and deceleration do not count towards task duration. Stop produces cancelled after deceleration. Normal completion produces completed after deceleration. Fault and uncertain outcomes cannot become completed. Backend restart marks the old Run and unfinished tasks interrupted. Users must start a new Run explicitly. The browser rotates built-in rotors from observed RPM. Imported GLB appearances have no rotor mapping.</p><p>The implementation preserves source scale, reports external-resource dependencies, absent geometry and decoder failures, and keeps the previous usable model on failure. Each node loads and releases independent model resources; selecting one instance does not rewrite another&#39;s materials. World snapshots return assets referenced by nodes and unplaced objects, so model recovery does not depend on the first catalog page.</p><p>Three.js code is loaded with the Lab page and checked against production bundle budgets. Preview builds and software-rendering measurements do not establish target-hardware performance.</p><h2 id="continue-development" tabindex="-1">Continue Development <a class="header-anchor" href="#continue-development" aria-label="Permalink to &quot;Continue Development&quot;">​</a></h2><p>Follow the <a href="./../tutorials/complete-foundation">complete journey</a> for the delivered Foundation V1 learning path and capacity limits. Physical devices, robot motion and autonomous experiment planning remain future scope. <a href="./module-boundaries">Module boundaries</a> define ownership.</p><hr><p>Source version：<code>847a4609ed29</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/847a4609ed29871c5721b4e03dc3edd3953b8f28/docs/architecture/lab-word.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,21)])])}const m=t(i,[["render",s]]);export{h as __pageData,m as default};
